exercises.solution:
const installedBins = ["jest", "esbuild"];
function npx(bin) {
  if (installedBins.includes(bin)) {
    console.log("running local " + bin);
  } else {
    console.log("fetching " + bin + " from the registry");
  }
}
npx("jest");
npx("cowsay");

